SELECT conversion_event_marketplace_name, COUNT(DISTINCT CASE WHEN new_to_brand THEN user_id END) AS buyers_new_to_brand_12mo, COUNT(DISTINCT user_id) AS buyers_attributed, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM amazon_attributed_events_by_conversion_time WHERE conversion_event_category = 'purchase' AND purchases > 0 AND user_id IS NOT NULL AND conversion_event_marketplace_name = CUSTOM_PARAMETER('sponsored_marketplace_name') GROUP BY conversion_event_marketplace_name
